[
  {
    "statement": "One field study in South Africa reported reduced growth of parrot’s feather following the release of a South American leaf-feeding Lysathia beetle.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "Two replicated, randomized field studies in Argentina and the USA found that stocking with grass carp reduced the biomass or abundance of parrot’s feather.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "One replicated, controlled laboratory study in Portugal found that grass carp did not reduce the biomass or cover of parrot’s feather.",
    "citations": [
