[
  {
    "statement": "A study in the USA found that an unmanaged and a partially managed orchard had a greater species richness and diversity of leaf-eating arthropods, including caterpillars, than a commercially managed orchard.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In Germany, a study found that managed orchards had a lower abundance of butterflies and burnet moths than abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "Another study in the USA found that vineyards managed to encourage native plants, and where insecticide was rarely used, had a greater abundance of butterflies than conventionally managed vineyards.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "A study in Spain found that vineyards managed with fewer chemicals had a greater species richness of butterflies than conventionally managed vineyards.",
    "citations": [
      "3919"
    ]
  }
]

[
  {
    "statement": "One study in the UK found that providing training for land managers, farmers, and farm advisers led to 82% of landowners who received advice submitting applications for an agri-environment scheme.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "The submitted agri-environment scheme applications had a 90% success rate.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "The successful applications resulted in over 3,000 ha of farmland being managed for the marsh fritillary.",
    "citations": [
      "3846"
    ]
  },
